sys_script_client.script:
function onSubmit() {

	if(g_user.hasRole('x_1590789_aoopemy.training_administrator') && g_form.isNewRecord()) {
		var scheduleSysId = g_form.getValue('training_schedules');

		alert('Cheguei 2 ');
		g_form.setValue('state', 3);

		updateSeats(scheduleSysId);

		return true;

	}

}

// Função para atualizar as vagas
function updateSeats(scheduleSysId) {
    var ga = new GlideAjax('AooPemyUtilsAjax');
    ga.addParam('sysparm_name', 'updateSeats');
    ga.addParam('sysparm_training_name', scheduleSysId);
    ga.getXMLAnswer(function(response) {
        if (response === 'true') {
            console.log('Vagas atualizadas com sucesso!')
			//gs.addInfoMessage('Vagas atualizadas com sucesso!');
        } else {
            console.log('Erro ao atualizar vagas.')

			//gs.addErrorMessage('Erro ao atualizar vagas.');
        }
    });

}
